      var regex = /\\\(([^]+?)\\\)|\\\[([^]+?)\\\]|\$\$([^]+?)\$\$|\$([^]+?)\$/g;
      var match;
      var found = null;
      while ((match = regex.exec(fullText)) !== null) {
        var start = match.index;
        var end = match.index + match[0].length;
        if (charPos >= start && charPos <= end) {
          found = {
            full: match[0],
            formula: match[1] || match[2] || match[3] || match[4],
            start: start,
            end: end,
            type: match[0].startsWith('\\(') ? 'inline' : match[0].startsWith('\\[') ? 'block' : match[0].startsWith('$$') ? 'block-dollar' : 'inline-dollar'
          };
          break;
        }
      }
      if (found) {
        this.showMathFormulaEditor(found, cm);
      }
